-- Fixed 2026-09-20: GEOCODE_LATITUDE/GEOCODE_LONGITUDE were bare try_to_double()
-- calls -- unguarded against the string 'nan' silently parsing as the float NaN,
-- which then poisons any average/sum it touches. Live-checked 2026-09-20: 0 of
-- 1,133,279 filled GEOCODE_LATITUDE rows are the string 'nan' today -- fixed as
-- a landmine, not an active bug. Kept on source() (not ref()): the sibling
-- staging model (models/staging/fed_epa_npdes_icis_facilities) leaves these two
-- columns as raw text (not every sampled value parsed as a float there), so
-- swapping to ref() would have demoted a currently-working DOUBLE column to
-- TEXT. Wrapped in place with stg_float instead (macros/staging_casts.sql).

with source as (
    select * from {{ source('ripple_raw', 'FED_EPA_NPDES_ICIS_FACILITIES') }}
)

select
    ICIS_FACILITY_INTEREST_ID as icis_facility_interest_id,
    NPDES_ID as npdes_id,
    FACILITY_UIN as facility_uin,
    FACILITY_TYPE_CODE as facility_type_code,
    FACILITY_NAME as facility_name,
    LOCATION_ADDRESS as location_address,
    SUPPLEMENTAL_ADDRESS_TEXT as supplemental_address_text,
    CITY as city,
    COUNTY_CODE as county_code,
    STATE_CODE as state_code,
    ZIP as zip,
    {{ stg_float('"GEOCODE_LATITUDE"') }} as geocode_latitude,
    {{ stg_float('"GEOCODE_LONGITUDE"') }} as geocode_longitude,
    IMPAIRED_WATERS as impaired_waters
from source
